(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w2 = Math.cos(x*0.025-t*0.4)*8+Math.sin(y*0.02+t*0.15)*6;
  const sx = x+w1+w2, sy = y+w1*0.7+w2*1.2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.2],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.5],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,5.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*50,0.11,2.1,4.3],
    [400+Math.cos(t*0.55+1)*60,200+Math.sin(t*0.75+4)*40,0.05,2.8,1.9]
  ];
  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp+ph);
    aS+=wave;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph);
    cS+=Math.sin(d*f*1.3-t*sp*0.4+ph*2)*0.6;
  }
  aS/=8;iS/=8;cS/=8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const ripple=Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.008)*0.3;
  const fractal=Math.sin(sx*0.07+Math.sin(sy*0.05+t)*3)*Math.cos(sy*0.06+Math.cos(sx*0.04-t)*2)*0.25;
  const rd1=aS-iS*0.7+cS*0.3;
  const rd2=Math.tanh((iS-aS*0.5)*1.5+bg*0.4);
  const feed=0.055+bg*0.015,kill=0.062+spiral*0.01;
  const reaction=Math.tanh((rd1*(1+feed)-rd2*kill+bg*0.3+spiral+ripple+fractal)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+t*4)*Math.sin(sy*0.25-t*3)*0.08;
  const blend=reaction*0.6+cell*0.25+micro+rd2*0.15;
  const v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,45,88],[18,95,118],[30,148,132],[90,178,120],
    [180,185,70],[220,165,55],[210,115,60],[175,60,58],[110,30,55],
    [55,18,62],[20,12,50],[6,12,52]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.18:Math.abs(reaction)>0.4?1.06:1.0;
  const glow=Math.max(0,1-Math.abs(reaction)*1.5)*0.15;
  const r=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  return[
    Math.min(255,((r+lum*30+glow*40)*lum*edge))|0,
    Math.min(255,((g+lum*20+glow*50)*lum*edge))|0,
    Math.min(255,((b+lum*40+glow*60)*lum*edge))|0
  ];
}
